// Full internal document entity
interface Document {
  id: string;
  tenantId: string;
  title: string;
  content: string;
  filePath: string;
  mimeType: string;
  securityGroups: string[];
  embeddingModel: string;
  createdAt: Date;
  updatedAt: Date;
  isIndexed: boolean;
}

// Omit<T, K>: Remove server-generated fields to create the upload DTO
type CreateDocumentDto = Omit<Document, 'id' | 'createdAt' | 'updatedAt' | 'isIndexed' | 'embeddingModel'>;

// Partial<Pick<T, K>>: Only the fields allowed for patch updates
type UpdateDocumentDto = Partial<Pick<Document, 'title' | 'securityGroups'>>;

// Pick<T, K>: Public summary for sidebar display (no content or paths)
type DocumentSummary = Pick<Document, 'id' | 'title' | 'mimeType' | 'isIndexed' | 'createdAt'>;

// Readonly<T>: Freeze the response after fetching to prevent accidental mutation
type ImmutableDocument = Readonly<Document>;

// Record<K, V>: Index documents by their string ID
type DocumentIndex = Record<string, DocumentSummary>;

import type { fetchChatCompletion, searchDocuments } from './aiClient';

// ReturnType<T>: Unwrap what the function returns
type RawSearchResult = Awaited<ReturnType<typeof searchDocuments>>;
// If searchDocuments returns Promise<{ chunks: Chunk[]; totalCount: number }>
// RawSearchResult = { chunks: Chunk[]; totalCount: number }

// Parameters<T>[N]: Extract the Nth argument type
type SearchOptions = Parameters<typeof searchDocuments>[1];
// If signature is searchDocuments(query: string, options: SearchOptions)
// We get the SearchOptions type without manually defining it

// Real usage: extending third-party types safely
interface ExtendedSearchOptions extends SearchOptions {
  includeSecurityGroups?: string[];
  minRRFScore?: number;
}

// Awaited<T>: Unwrap Promise types for synchronous contexts
type CompletionResponse = Awaited<ReturnType<typeof fetchChatCompletion>>;
// Works even with chained Promises: Awaited<Promise<Promise<T>>> = T

type SseEvent =
  | { type: 'token'; content: string }
  | { type: 'citation'; chunkId: string; documentTitle: string }
  | { type: 'tool_start'; toolName: string }
  | { type: 'tool_result'; toolName: string; result: unknown }
  | { type: 'error'; code: string; message: string }
  | { type: 'done' };

// Extract<T, U>: Keep only members of T assignable to U
type StreamingEvents = Extract<SseEvent, { type: 'token' | 'citation' }>;
// = { type: 'token'; content: string } | { type: 'citation'; chunkId: string; documentTitle: string }

// Exclude<T, U>: Remove members of T assignable to U
type TerminalEvents = Exclude<SseEvent, { type: 'token' | 'citation' | 'tool_start' | 'tool_result' }>;
// = { type: 'error'; code: string; message: string } | { type: 'done' }

// Type-safe dispatcher using extracted union
function handleStreamEvent(event: SseEvent) {
  switch (event.type) {
    case 'token': appendToken(event.content); break;
    case 'citation': addCitation(event.chunkId, event.documentTitle); break;
    case 'error': showError(event.message); break;
    case 'done': finalizeStream(); break;
    case 'tool_start': showToolSpinner(event.toolName); break;
    case 'tool_result': dismissToolSpinner(event.toolName); break;
    // TypeScript exhaustiveness: no default needed since all cases covered
  }
}

declare function appendToken(c: string): void;
declare function addCitation(id: string, title: string): void;
declare function showError(msg: string): void;
declare function finalizeStream(): void;
declare function showToolSpinner(name: string): void;
declare function dismissToolSpinner(name: string): void;
